import sys, json
d = json.load(sys.stdin)["body"]
user = next((m for m in d.get("messages", [])
             if m.get("origin") == "user" and m.get("type") == "text"), None)
if user is None:
    sys.stdout.write("[]"); sys.exit(0)
TOOLS = {
    "lookup": {"description": "Look up a short fact about a topic.",
               "parameters": {"type": "object",
                              "properties": {"topic": {"type": "string"}},
                              "required": ["topic"]}},
    "calc": {"description": "Evaluate a simple arithmetic expression, e.g. '6 * 7'.",
             "parameters": {"type": "object",
                            "properties": {"expr": {"type": "string"}},
                            "required": ["expr"]}},
}
out = [{
    "header": {"question": user.get("text", "")},
    "system": {
        "identity": {"soul": {"text": (
            "You are a small agent running inside a meclaw swarm. "
            "Use a tool when it helps, one tool call at a time. "
            "When a tool result answers the question, reply with a short final "
            "answer in plain text and do not call another tool.")}},
        "tools": {name: {"text": json.dumps(
            {"type": "function", "function": {"name": name, **schema}})}
            for name, schema in TOOLS.items()},
    },
    "messages": [user],
}]
sys.stdout.write(json.dumps(out))
